'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var Complex64Array = require( '@stdlib/array/complex64' );
var tryRequire = require( '@stdlib/utils/try-require' );


// VARIABLES //

var clastIndexOfFalsy = tryRequire( resolve( __dirname, './../lib/clast_index_of_falsy.native.js' ) );
var opts = {
	'skip': ( clastIndexOfFalsy instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof clastIndexOfFalsy, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 3', opts, function test( t ) {
	t.strictEqual( clastIndexOfFalsy.length, 3, 'has expected arity' );
	t.end();
});

tape( 'the function returns the index of the last falsy element', opts, function test( t ) {
	var actual;
	var x;

	x = new Complex64Array( [ 1.0, 2.0, 0.0, 0.0, 2.0, 3.0, 0.0, 0.0, 0.0, 0.0, 4.0, 5.0 ] );

	actual = clastIndexOfFalsy( x.length, x, 1 );
	t.strictEqual( actual, 4, 'returns expected value' );

	x = new Complex64Array( [ 1.0, 2.0, 2.0, 3.0, 3.0, 4.0, 0.0, 0.0 ] );

	actual = clastIndexOfFalsy( x.length, x, 1 );
	t.strictEqual( actual, 3, 'returns expected value' );

	t.end();
});

tape( 'the function returns `-1` if provided an `N` parameter less than or equal to 0', opts, function test( t ) {
	var actual;
	var x;

	x = new Complex64Array( [ 1.0, 2.0, 0.0, 0.0, 2.0, 3.0 ] );

	actual = clastIndexOfFalsy( 0, x, 1 );
	t.strictEqual( actual, -1, 'returns expected value' );

	actual = clastIndexOfFalsy( -1, x, 1 );
	t.strictEqual( actual, -1, 'returns expected value' );

	t.end();
});

tape( 'the function supports an `x` stride', opts, function test( t ) {
	var actual;
	var x;

	x = new Complex64Array( [ 1.0, 2.0, 0.0, 0.0, 2.0, 3.0, 3.0, 4.0, 0.0, 0.0, 5.0, 6.0 ] );

	actual = clastIndexOfFalsy( 3, x, 2 );
	t.strictEqual( actual, 2, 'returns expected value' );

	x = new Complex64Array( [ 1.0, 2.0, 2.0, 3.0, 0.0, 0.0, 3.0, 4.0, 4.0, 5.0 ] );

	actual = clastIndexOfFalsy( 2, x, 2 );
	t.strictEqual( actual, 1, 'returns expected value' );

	t.end();
});

tape( 'the function supports a negative `x` stride', opts, function test( t ) {
	var actual;
	var x;

	x = new Complex64Array( [ 1.0, 2.0, 0.0, 0.0, 2.0, 3.0, 3.0, 4.0, 0.0, 0.0 ] );

	actual = clastIndexOfFalsy( 3, x, -2 );
	t.strictEqual( actual, 0, 'returns expected value' );

	t.end();
});

tape( 'the function supports complex access patterns', opts, function test( t ) {
	var actual;
	var x;

	x = new Complex64Array( [ 0.0, 0.0, 1.0, 2.0, 0.0, 0.0, 2.0, 3.0, 0.0, 0.0 ] );

	actual = clastIndexOfFalsy( 3, x, 2 );
	t.strictEqual( actual, 2, 'returns expected value' );

	t.end();
});

tape( 'the function explicitly treats `NaN` values as falsy', opts, function test( t ) {
	var actual;
	var x;

	x = new Complex64Array( [ 1.0, 2.0, NaN, NaN, 2.0, 3.0 ] );

	actual = clastIndexOfFalsy( 3, x, 1 );
	t.strictEqual( actual, 1, 'returns expected value' );

	x = new Complex64Array( [ 1.0, 2.0, NaN, 0.0, 2.0, 3.0 ] );

	actual = clastIndexOfFalsy( 3, x, 1 );
	t.strictEqual( actual, 1, 'returns expected value' );

	x = new Complex64Array( [ 1.0, 2.0, 0.0, NaN, 2.0, 3.0 ] );

	actual = clastIndexOfFalsy( 3, x, 1 );
	t.strictEqual( actual, 1, 'returns expected value' );

	t.end();
});

tape( 'the function returns `-1` if unable to find a falsy element', opts, function test( t ) {
	var actual;
	var x;

	x = new Complex64Array( [ 1.0, 2.0, 2.0, 3.0, 3.0, 4.0 ] );

	actual = clastIndexOfFalsy( 3, x, 1 );
	t.strictEqual( actual, -1, 'returns expected value' );

	t.end();
});

tape( 'the function supports view offsets', opts, function test( t ) {
	var actual;
	var x0;
	var x1;

	x0 = new Complex64Array( [ 1.0, 2.0, 0.0, 0.0, 2.0, 3.0, 3.0, 4.0, 0.0, 0.0, 5.0, 6.0 ] );

	x1 = new Complex64Array( x0.buffer, x0.BYTES_PER_ELEMENT*1 );

	actual = clastIndexOfFalsy( 3, x1, 2 );
	t.strictEqual( actual, 0, 'returns expected value' );

	t.end();
});
